export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon?: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";
type FailedAt = Provider | "repository";

export type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Rejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Rejection[];
}

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type InvalidOrMissingBody = {
  code: "invalid_command" | "not_found" | "service_unavailable";
};

type AbortBody = {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: FailedAt;
  classification: AbortClassification;
  rejections: Rejection[];
};

export interface ServiceResponse {
  status: number;
  body: PublicShipment | InvalidOrMissingBody | AbortBody;
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierOutcome =
  | Readonly<{ kind: "confirmed"; provider: Provider; bookingId: string }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "throttled"; provider: Provider; retryAtMs: number }>
  | Readonly<{
      kind: "aborted";
      failedAt: Provider;
      classification: Exclude<AbortClassification, "repository_failure">;
    }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value);
}

function isPositiveSafeInteger(value: unknown): value is number {
  return isSafeInteger(value) && value > 0;
}

function parseRejections(value: unknown): Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const parsed: Rejection[] = [];
  for (const item of value) {
    if (!isObject(item) || !isProvider(item.provider) || !isRefusalReason(item.reason)) {
      return undefined;
    }
    parsed.push({ provider: item.provider, reason: item.reason });
  }
  return parsed;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    !isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    typeof value.id !== "string" ||
    value.id.length === 0 ||
    typeof value.routeCode !== "string" ||
    value.routeCode.length === 0 ||
    !isPositiveSafeInteger(value.parcelGrams)
  ) {
    return undefined;
  }

  const fields: ShipmentFields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  };

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    typeof value.bookingId === "string" &&
    value.bookingId.length > 0 &&
    isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }

  const rejections = parseRejections(value.rejections);
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    isSafeInteger(value.retryAtMs) &&
    value.retryAtMs >= 0 &&
    rejections !== undefined
  ) {
    return {
      ...fields,
      state: "deferred",
      nextProvider: value.nextProvider,
      retryAtMs: value.retryAtMs,
      rejections,
    };
  }
  if (value.state === "unavailable" && rejections !== undefined) {
    return { ...fields, state: "unavailable", rejections };
  }

  return undefined;
}

function basePublicFields(shipment: StoredShipment) {
  return {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = basePublicFields(shipment);
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections.map(copyRejection),
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: shipment.rejections.map(copyRejection),
      };
  }
}

function copyRejection(rejection: Rejection): Rejection {
  return { provider: rejection.provider, reason: rejection.reason };
}

function copyRejections(rejections: readonly Rejection[]): Rejection[] {
  return rejections.map(copyRejection);
}

function abortBody(
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: readonly Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: copyRejections(rejections),
  };
}

function abortResponse(
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: readonly Rejection[],
): ServiceResponse {
  return {
    status: 500,
    body: abortBody(shipmentId, failedAt, classification, rejections),
  };
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function classifyAtlasRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error) || typeof error.code !== "string") {
    return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
  }
  if (error.code === "cannot_ship") {
    if (isRefusalReason(error.reason)) {
      return { kind: "refused", rejection: { provider: "atlas", reason: error.reason } };
    }
    return { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
  }
  if (error.code === "rate_limited") {
    if (isSafeInteger(error.retryAtMs) && error.retryAtMs > nowMs) {
      return { kind: "throttled", provider: "atlas", retryAtMs: error.retryAtMs };
    }
    return { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
}

function classifyBeaconRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error) || typeof error.type !== "string") {
    return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
  }
  if (error.type === "rejected") {
    if (isObject(error.details) && isRefusalReason(error.details.reason)) {
      return { kind: "refused", rejection: { provider: "beacon", reason: error.details.reason } };
    }
    return { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
  }
  if (error.type === "throttled") {
    if (
      isObject(error.details) &&
      isSafeInteger(error.details.retryAtMs) &&
      error.details.retryAtMs > nowMs
    ) {
      return { kind: "throttled", provider: "beacon", retryAtMs: error.details.retryAtMs };
    }
    return { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
}

function classifyConfirmation(provider: Provider, confirmation: unknown): CarrierOutcome {
  if (provider === "atlas") {
    if (isObject(confirmation) && typeof confirmation.bookingId === "string" && confirmation.bookingId.length > 0) {
      return { kind: "confirmed", provider, bookingId: confirmation.bookingId };
    }
    return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
  }

  if (isObject(confirmation) && typeof confirmation.reference === "string" && confirmation.reference.length > 0) {
    return { kind: "confirmed", provider, bookingId: confirmation.reference };
  }
  return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
}

export function createShippingService(dependencies: ShippingDependencies) {
  function emitAbort(
    shipmentId: string,
    failedAt: FailedAt,
    classification: AbortClassification,
    rejections: readonly Rejection[],
  ): void {
    dependencies.logger.info({
      shipmentId,
      action: "aborted",
      failedAt,
      classification,
      rejections: copyRejections(rejections),
    });
  }

  async function saveDecision(
    shipment: StoredShipment,
    record: StoredShipment,
    event: Record<string, unknown>,
    saveFailureRejections: readonly Rejection[],
  ): Promise<ServiceResponse | undefined> {
    try {
      await dependencies.repository.save(shipment.id, record);
    } catch {
      emitAbort(shipment.id, "repository", "repository_failure", saveFailureRejections);
      return abortResponse(
        shipment.id,
        "repository",
        "repository_failure",
        saveFailureRejections,
      );
    }
    dependencies.logger.info(event);
    const status = record.state === "deferred" ? 202 : record.state === "unavailable" ? 422 : 200;
    return { status, body: publicShipment(record) };
  }

  async function attemptCarrier(
    provider: Provider,
    shipment: StoredShipment,
    command: Extract<Command, { op: "dispatch" }>,
  ): Promise<CarrierOutcome> {
    try {
      const request = providerRequest(shipment, command.recipient);
      const confirmation =
        provider === "atlas"
          ? await dependencies.atlas.book(request)
          : await dependencies.beacon?.reserve(request);
      return classifyConfirmation(provider, confirmation);
    } catch (error) {
      return provider === "atlas"
        ? classifyAtlasRejection(error, command.nowMs)
        : classifyBeaconRejection(error, command.nowMs);
    }
  }

  async function persistDispatched(
    shipment: StoredShipment,
    command: Extract<Command, { op: "dispatch" }>,
    outcome: Extract<CarrierOutcome, { kind: "confirmed" }>,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    const dispatched: DispatchedShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "dispatched",
      provider: outcome.provider,
      bookingId: outcome.bookingId,
      dispatchedAtMs: command.nowMs,
    };
    const result = await saveDecision(
      shipment,
      dispatched,
      {
        shipmentId: shipment.id,
        action: "dispatched",
        provider: outcome.provider,
      },
      rejections,
    );
    return result ?? abortResponse(shipment.id, "repository", "repository_failure", rejections);
  }

  async function persistDeferred(
    shipment: StoredShipment,
    outcome: Extract<CarrierOutcome, { kind: "throttled" }>,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    const deferred: DeferredShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "deferred",
      nextProvider: outcome.provider,
      retryAtMs: outcome.retryAtMs,
      rejections: copyRejections(rejections),
    };
    const result = await saveDecision(
      shipment,
      deferred,
      {
        shipmentId: shipment.id,
        action: "deferred",
        provider: outcome.provider,
        retryAtMs: outcome.retryAtMs,
        rejections: copyRejections(rejections),
      },
      rejections,
    );
    return result ?? abortResponse(shipment.id, "repository", "repository_failure", rejections);
  }

  async function persistUnavailable(
    shipment: StoredShipment,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "unavailable",
      rejections: copyRejections(rejections),
    };
    const result = await saveDecision(
      shipment,
      unavailable,
      {
        shipmentId: shipment.id,
        action: "unavailable",
        rejections: copyRejections(rejections),
      },
      rejections,
    );
    return result ?? abortResponse(shipment.id, "repository", "repository_failure", rejections);
  }

  async function dispatchFrom(
    shipment: StoredShipment,
    command: Extract<Command, { op: "dispatch" }>,
    provider: Provider,
    retainedRejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    if (retainedRejections.some((rejection) => rejection.provider === provider)) {
      emitAbort(shipment.id, provider, "invalid_provider_response", retainedRejections);
      return abortResponse(shipment.id, provider, "invalid_provider_response", retainedRejections);
    }

    const outcome = await attemptCarrier(provider, shipment, command);
    switch (outcome.kind) {
      case "confirmed":
        return persistDispatched(shipment, command, outcome, retainedRejections);
      case "throttled":
        return persistDeferred(shipment, outcome, retainedRejections);
      case "aborted":
        emitAbort(shipment.id, outcome.failedAt, outcome.classification, retainedRejections);
        return abortResponse(
          shipment.id,
          outcome.failedAt,
          outcome.classification,
          retainedRejections,
        );
      case "refused": {
        const rejections = [...copyRejections(retainedRejections), outcome.rejection];
        if (outcome.rejection.provider === "atlas") {
          return dispatchFrom(shipment, command, "beacon", rejections);
        }
        return persistUnavailable(shipment, rejections);
      }
    }
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      emitAbort(command.shipmentId, "repository", "repository_failure", []);
      return abortResponse(command.shipmentId, "repository", "repository_failure", []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (shipment === undefined) {
      emitAbort(command.shipmentId, "repository", "repository_failure", []);
      return abortResponse(command.shipmentId, "repository", "repository_failure", []);
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred") {
      if (command.nowMs < shipment.retryAtMs) {
        return { status: 202, body: publicShipment(shipment) };
      }
      return dispatchFrom(shipment, command, shipment.nextProvider, shipment.rejections);
    }

    return dispatchFrom(shipment, command, "atlas", []);
  }

  return { handle };
}
